CREATE TABLE IF NOT EXISTS hr_staff_access (member_wix_id text PRIMARY KEY, role text NOT NULL CHECK (role IN ('manager','candidate')), created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS hr_professional_reviews (application_id uuid NOT NULL REFERENCES hr_applications(id), reviewer_wix_id text NOT NULL, subject_wix_id text NOT NULL, reviewer_role text NOT NULL CHECK (reviewer_role IN ('candidate','recruiter')), rating integer NOT NULL CHECK (rating BETWEEN 1 AND 5), comment text NOT NULL CHECK (char_length(btrim(comment)) BETWEEN 5 AND 1500), created_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(application_id,reviewer_role), CHECK(reviewer_wix_id <> subject_wix_id));
